using System.Text.Json;
using AeppGenerator.Api.Gamification;
using Microsoft.Data.Sqlite;
namespace AeppGenerator.Api.Data;
public sealed record AccountUser(string Id,string Email,string PasswordHash,string FullName,string Role,string CreatedAt);
public sealed record UserProgress(string UserId,int TotalXP,int CurrentStreak,int MaxStreak,string? LastChallengeDate,string[] Badges);
public sealed record SavedExam(string Id,string Title,string Format,string CreatedAt);
public sealed partial class AccountStore {
 private readonly string connectionString;
 public string ConnectionString => connectionString; private readonly SemaphoreSlim gate=new(1,1);
 private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);
 public AccountStore(string path){Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);connectionString=new SqliteConnectionStringBuilder{DataSource=Path.GetFullPath(path),ForeignKeys=true,DefaultTimeout=15}.ToString();using var connection=Open();using var schema=typeof(AccountStore).Assembly.GetManifestResourceStream("AeppGenerator.AccountSchema")!;using var reader=new StreamReader(schema);using var command=connection.CreateCommand();command.CommandText=reader.ReadToEnd();command.ExecuteNonQuery();ProgressMigration.Apply(connection);}
 private SqliteConnection Open(){var connection=new SqliteConnection(connectionString);connection.Open();return connection;}
 public Action<string>? ObserveCommand { get; set; }
 private SqliteCommand Command(SqliteConnection c,SqliteTransaction? t,string sql,params (string,object?)[] values){var cmd=c.CreateCommand();cmd.Transaction=t;cmd.CommandText=sql;ObserveCommand?.Invoke(sql);foreach(var (key,value) in values)cmd.Parameters.AddWithValue(key,value??DBNull.Value);return cmd;}
 private static AccountUser User(SqliteDataReader r)=>new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5));
 public AccountUser? FindEmail(string email){using var c=Open();using var cmd=Command(c,null,"SELECT Id,Email,PasswordHash,FullName,Role,CreatedAt FROM Users WHERE NormalizedEmail=$email",("$email",email.Trim().ToUpperInvariant()));using var r=cmd.ExecuteReader();return r.Read()?User(r):null;}
 public AccountUser? FindUser(string id){using var c=Open();using var cmd=Command(c,null,"SELECT Id,Email,PasswordHash,FullName,Role,CreatedAt FROM Users WHERE Id=$id",("$id",id));using var r=cmd.ExecuteReader();return r.Read()?User(r):null;}
 public async Task<AccountUser> Register(string email,string hash,string name){await gate.WaitAsync();try{using var c=Open();using var tx=c.BeginTransaction(deferred:false);var user=new AccountUser(Guid.NewGuid().ToString(),email.Trim(),hash,name.Trim(),"STUDENT",DateTimeOffset.UtcNow.ToString("O"));using(var cmd=Command(c,tx,"INSERT INTO Users VALUES($id,$email,$normalized,$hash,$name,$role,$created)",("$id",user.Id),("$email",user.Email),("$normalized",user.Email.ToUpperInvariant()),("$hash",hash),("$name",user.FullName),("$role",user.Role),("$created",user.CreatedAt)))cmd.ExecuteNonQuery();using(var cmd=Command(c,tx,"INSERT INTO UserProgress(UserId,PublicCode,Username) VALUES($id,$code,$name)",("$id",user.Id),("$code",Guid.NewGuid().ToString("N")[..12]),("$name",user.FullName.Length>24?user.FullName[..24]:user.FullName)))cmd.ExecuteNonQuery();tx.Commit();return user;}catch(SqliteException e)when(e.SqliteErrorCode==19){throw new DuplicateEmailException();}finally{gate.Release();}}
 public UserProgress Progress(string id){using var c=Open();var day=TimeZoneInfo.ConvertTime(DateTimeOffset.UtcNow,TimeZoneInfo.FindSystemTimeZoneById("Europe/Athens")).ToString("yyyy-MM-dd");using var cmd=Command(c,null,"SELECT UserId,TotalXP,CASE WHEN LastActivityDate BETWEEN $yesterday AND $day THEN CurrentStreak ELSE 0 END,MaxStreak,LastChallengeDate,Badges FROM UserProgress WHERE UserId=$id",("$id",id),("$day",day),("$yesterday",DateOnly.Parse(day).AddDays(-1).ToString("yyyy-MM-dd")));using var r=cmd.ExecuteReader();if(!r.Read())throw new UnauthorizedAccessException();return new(r.GetString(0),r.GetInt32(1),r.GetInt32(2),r.GetInt32(3),r.IsDBNull(4)?null:r.GetString(4),JsonSerializer.Deserialize<string[]>(r.GetString(5))!);}
 public void AddSession(string id,string user,long expires){using var c=Open();using var cmd=Command(c,null,"INSERT INTO AuthSessions VALUES($id,$user,$expires,0)",("$id",id),("$user",user),("$expires",expires));cmd.ExecuteNonQuery();}
 public bool ValidSession(string id,string user,string role){using var c=Open();using var cmd=Command(c,null,"SELECT COUNT(*) FROM AuthSessions s JOIN Users u ON u.Id=s.UserId WHERE s.Id=$id AND s.UserId=$user AND s.ExpiresAt>$now AND s.Revoked=0 AND u.Role=$role",("$id",id),("$user",user),("$now",DateTimeOffset.UtcNow.ToUnixTimeSeconds()),("$role",role));return Convert.ToInt32(cmd.ExecuteScalar())==1;}
 public bool PromoteTeacher(string email){using var c=Open();using var tx=c.BeginTransaction(deferred:false);using var cmd=Command(c,tx,"UPDATE Users SET Role='TEACHER' WHERE NormalizedEmail=$email",("$email",email.Trim().ToUpperInvariant()));var changed=cmd.ExecuteNonQuery();using var revoke=Command(c,tx,"UPDATE AuthSessions SET Revoked=1 WHERE UserId IN (SELECT Id FROM Users WHERE NormalizedEmail=$email)",("$email",email.Trim().ToUpperInvariant()));revoke.ExecuteNonQuery();tx.Commit();return changed==1;}
 public void Revoke(string id,string user){using var c=Open();using var cmd=Command(c,null,"UPDATE AuthSessions SET Revoked=1 WHERE Id=$id AND UserId=$user",("$id",id),("$user",user));cmd.ExecuteNonQuery();}
 public SavedExam SaveExam(string user,string title,string format,string json){var exam=new SavedExam(Guid.NewGuid().ToString(),title,format,DateTimeOffset.UtcNow.ToString("O"));using var c=Open();using var cmd=Command(c,null,"INSERT INTO SavedExams VALUES($id,$user,$title,$format,$json,$at)",("$id",exam.Id),("$user",user),("$title",title),("$format",format),("$json",json),("$at",exam.CreatedAt));cmd.ExecuteNonQuery();return exam;}
 public List<SavedExam> Exams(string user){using var c=Open();using var cmd=Command(c,null,"SELECT Id,Title,Format,CreatedAt FROM SavedExams WHERE UserId=$user ORDER BY CreatedAt DESC LIMIT 100",("$user",user));using var r=cmd.ExecuteReader();List<SavedExam> exams=[];while(r.Read())exams.Add(new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3)));return exams;}
 public string? Exam(string user,string id){using var c=Open();using var cmd=Command(c,null,"SELECT ContentJson FROM SavedExams WHERE Id=$id AND UserId=$user",("$id",id),("$user",user));return cmd.ExecuteScalar() as string;}
}
public sealed class DuplicateEmailException:Exception {}
